resources.preRequestScript:
const runId = Date.now().toString();
const clear = ['admin_token','driver_token','driver_id','facility_id','station_id','connector_id','vehicle_id','simulation_run_id','simulation_run_token','reservation_id','session_id','simulator_driver_tokens_json','scenario_json','draft_bootstrap_json','bootstrap_json','simulator_env','SIMULATION_RUN_TOKEN','SIMULATION_DRIVER_TOKENS_JSON'];
insomnia.baseEnvironment.set('run_id', runId);
clear.forEach(name => insomnia.baseEnvironment.set(name, ''));
insomnia.baseEnvironment.set('logical_start_at', '2026-01-05T00:00:00.000Z');
insomnia.baseEnvironment.set('logical_end_at', '2026-01-06T00:00:00.000Z');

resources.afterResponseScript:
const body = insomnia.response.json();
insomnia.test('dedicated Facility creation returns 201', () => { insomnia.expect(insomnia.response.code).to.eql(201); insomnia.expect(body.timezone).to.eql('UTC'); insomnia.expect(body.status).to.eql('Active'); });
if (insomnia.response.code === 201) insomnia.baseEnvironment.set('facility_id', body.id);

const body = insomnia.response.json();
insomnia.test('Station with one available Connector returns 201', () => { insomnia.expect(insomnia.response.code).to.eql(201); insomnia.expect(body.facility_id).to.eql(insomnia.baseEnvironment.get('facility_id')); insomnia.expect(body.status).to.eql('Active'); insomnia.expect(body.connectors).to.have.length(1); insomnia.expect(body.connectors[0].status).to.eql('Available'); });
if (insomnia.response.code === 201) { insomnia.baseEnvironment.set('station_id', body.id); insomnia.baseEnvironment.set('connector_id', body.connectors[0].id); }

const body = insomnia.response.json();
insomnia.test('dedicated EVDriver creation returns 201', () => { insomnia.expect(insomnia.response.code).to.eql(201); insomnia.expect(body.roles).to.include('EVDriver'); insomnia.expect(body.status).to.eql('Active'); });
if (insomnia.response.code === 201) insomnia.baseEnvironment.set('driver_id', body.id);

const body = insomnia.response.json();
insomnia.test('EVDriver Vehicle creation returns 201', () => { insomnia.expect(insomnia.response.code).to.eql(201); insomnia.expect(body.owner_id).to.eql(insomnia.baseEnvironment.get('driver_id')); insomnia.expect(body.status).to.eql('ACTIVE'); });
if (insomnia.response.code === 201) insomnia.baseEnvironment.set('vehicle_id', body.id);

const body = insomnia.response.json();
insomnia.test('SimulationRun is created as DRAFT', () => { insomnia.expect(insomnia.response.code).to.eql(201); insomnia.expect(body.status).to.eql('DRAFT'); insomnia.expect(body.facility_ids).to.eql([insomnia.baseEnvironment.get('facility_id')]); insomnia.expect(body.evdriver_ids).to.eql([insomnia.baseEnvironment.get('driver_id')]); insomnia.expect(body.scenario_sha256).to.eql(null); });
if (insomnia.response.code === 201) insomnia.baseEnvironment.set('simulation_run_id', body.id);

const body = insomnia.response.json();
insomnia.test('DRAFT bootstrap contains only authorized identifiers and no credential', () => { insomnia.expect(insomnia.response.code).to.eql(200); insomnia.expect(body.simulation_run.status).to.eql('DRAFT'); insomnia.expect(body.authorized_facility_ids).to.eql([insomnia.baseEnvironment.get('facility_id')]); insomnia.expect(body.authorized_evdriver_ids).to.eql([insomnia.baseEnvironment.get('driver_id')]); insomnia.expect(JSON.stringify(body)).not.to.include('token'); });
if (insomnia.response.code === 200) insomnia.baseEnvironment.set('draft_bootstrap_json', JSON.stringify(body, null, 2));

const body = insomnia.response.json();
const env = insomnia.baseEnvironment;
insomnia.test('run starts and returns the one-time token', () => { insomnia.expect(insomnia.response.code).to.eql(200); insomnia.expect(body.simulation_run.status).to.eql('RUNNING'); insomnia.expect(body.simulation_token).to.be.a('string'); insomnia.expect(body.simulation_token.length).to.be.greaterThan(20); });
if (insomnia.response.code === 200) {
  const driverId = env.get('driver_id');
  const facilityId = env.get('facility_id');
  const driverTokens = JSON.stringify({[driverId]: env.get('driver_token')});
  const scenario = {schema_version:'1.0', scenario_id:'spec-013-insomnia-smoke', scenario_version:'1', random_seed:13013, logical_start_at:env.get('logical_start_at'), logical_end_at:env.get('logical_end_at'), telemetry_defaults:{enabled:true,sampling_interval_minutes:15,batch_size:100,bounded_power_noise:0}, drivers:[{driver_id:driverId,sessions_per_week:{min:1,max:1},weekday_weights:{'0':1},hour_weights:{'12':1},start_time_jitter_minutes:0,facility_weights:{[facilityId]:1},preferred_connector_types:['Type2'],selection_strategy:'FIRST_ELIGIBLE',reservation_probability:1,cancellation_probability:0,no_show_probability:0,lead_time_minutes:{min:60,max:60},session_duration_minutes:{min:60,max:60},power_utilization_factor:{min:0.5,max:0.5},telemetry:{enabled:true,sampling_interval_minutes:15,batch_size:100,bounded_power_noise:0},failure_handling:{try_another_connector:false,try_another_station:false,try_another_facility:false,maximum_alternative_attempts:0,rescheduling_delay_minutes:{min:15,max:15},maximum_rescheduling_attempts:0}}]};
  env.set('simulation_run_token', body.simulation_token);
  env.set('simulator_driver_tokens_json', driverTokens);
  env.set('scenario_json', JSON.stringify(scenario, null, 2));
  env.set('simulator_env', [
    `BACKEND_URL=${env.get('base_url')}`,
    `SIMULATION_SCENARIO_PATH=${env.get('simulator_scenario_path')}`,
    `SIMULATION_BOOTSTRAP_PATH=${env.get('simulator_bootstrap_path')}`,
    `SIMULATION_CHECKPOINT_PATH=${env.get('simulator_checkpoint_path')}`,
    `SIMULATION_REPORT_PATH=${env.get('simulator_report_path')}`,
    `SIMULATION_RUN_TOKEN=${body.simulation_token}`,
    `SIMULATION_DRIVER_TOKENS_JSON='${driverTokens}'`
  ].join('\n'));
}

resources.preRequestScript:
const env = insomnia.baseEnvironment;
env.set('BACKEND_URL', env.get('base_url'));
env.set('SIMULATION_SCENARIO_PATH', env.get('simulator_scenario_path'));
env.set('SIMULATION_BOOTSTRAP_PATH', env.get('simulator_bootstrap_path'));
env.set('SIMULATION_CHECKPOINT_PATH', env.get('simulator_checkpoint_path'));
env.set('SIMULATION_REPORT_PATH', env.get('simulator_report_path'));
env.set('SIMULATION_RUN_TOKEN', env.get('simulation_run_token'));
env.set('SIMULATION_DRIVER_TOKENS_JSON', env.get('simulator_driver_tokens_json'));

resources.afterResponseScript:
const body = insomnia.response.json();
insomnia.test('RUNNING bootstrap matches scenario authorization and window', () => { insomnia.expect(insomnia.response.code).to.eql(200); insomnia.expect(body.bootstrap_version).to.eql('1.0'); insomnia.expect(body.api_version).to.eql('1'); insomnia.expect(body.simulation_run.status).to.eql('RUNNING'); insomnia.expect(new Date(body.simulation_run.logical_start_at).toISOString()).to.eql(new Date(insomnia.baseEnvironment.get('logical_start_at')).toISOString()); insomnia.expect(new Date(body.simulation_run.logical_end_at).toISOString()).to.eql(new Date(insomnia.baseEnvironment.get('logical_end_at')).toISOString()); insomnia.expect(body.authorized_facility_ids).to.eql([insomnia.baseEnvironment.get('facility_id')]); insomnia.expect(body.authorized_evdriver_ids).to.eql([insomnia.baseEnvironment.get('driver_id')]); });
if (insomnia.response.code === 200) insomnia.baseEnvironment.set('bootstrap_json', JSON.stringify(body, null, 2));

const body = insomnia.response.json();
const driverId = insomnia.baseEnvironment.get('driver_id');
const vehicleId = insomnia.baseEnvironment.get('vehicle_id');
const matches = body.filter(item => item.owner_id === driverId && item.vehicle_id === vehicleId && item.status === 'COMPLETED');
insomnia.test('completed simulator Reservation is publicly visible', () => { insomnia.expect(insomnia.response.code).to.eql(200); insomnia.expect(matches.length).to.be.greaterThan(0); });
if (matches.length) insomnia.baseEnvironment.set('reservation_id', matches[0].id);

const body = insomnia.response.json();
const reservationId = insomnia.baseEnvironment.get('reservation_id');
const matches = body.filter(item => item.reservation_id === reservationId && item.status === 'COMPLETED');
insomnia.test('completed simulated Charging Session is publicly visible', () => { insomnia.expect(insomnia.response.code).to.eql(200); insomnia.expect(matches.length).to.be.greaterThan(0); });
if (matches.length) insomnia.baseEnvironment.set('session_id', matches[0].id);
